DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.start_learning_session(text,text)'::regprocedure) INTO d; d:=replace(d,'AND completed_at IS NULL AND (p_kind','AND completed_at IS NULL AND test_id IS NULL AND (p_kind');d:=replace(d,'WHERE published AND','WHERE published AND p=ANY(pathways) AND');EXECUTE d; END $$;
CREATE FUNCTION public.validate_test_rules() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.duration_minutes>0 AND NEW.instant_feedback AND NEW.kind<>'exam' THEN RAISE EXCEPTION 'Pour un test chronométré, désactivez la correction immédiate ; la correction sera affichée à la fin.'; END IF; IF NEW.status='published' AND (NEW.title='' OR cardinality(NEW.pathways)=0 OR NOT(NEW.pathways<@ARRAY['naturalisation','resident','sejour']) OR (NEW.kind='free' AND NEW.question_count<>10)) THEN RAISE EXCEPTION 'Règles du test invalides.'; END IF; RETURN NEW;END $$;
CREATE TRIGGER validate_test_rules BEFORE INSERT OR UPDATE ON public.learning_tests FOR EACH ROW EXECUTE FUNCTION public.validate_test_rules();
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.record_learning_attempt(jsonb)'::regprocedure) INTO d;d:=replace(d,'SELECT count(*),','SELECT parcours INTO p FROM public.profiles WHERE id=auth.uid(); SELECT count(*),');d:=replace(d,'WHERE published ORDER BY','WHERE published AND p=ANY(pathways) ORDER BY');EXECUTE d; END $$;
CREATE FUNCTION public.validate_published_source() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.published AND (TG_OP='INSERT' OR OLD.published IS DISTINCT FROM NEW.published OR OLD.question IS DISTINCT FROM NEW.question OR OLD.options IS DISTINCT FROM NEW.options) THEN IF NEW.source_url IS NULL OR NEW.source_url !~ '^https://([A-Za-z0-9-]+\.)*(gouv\.fr|service-public\.fr|vie-publique\.fr|legifrance\.gouv\.fr|assemblee-nationale\.fr|senat\.fr|elysee\.fr|conseil-constitutionnel\.fr)(/|$)' THEN RAISE EXCEPTION 'Une source officielle française est requise pour publier.'; END IF;NEW.source_status:='verifiee'; END IF;RETURN NEW;END $$;
CREATE TRIGGER validate_published_source BEFORE INSERT OR UPDATE ON public.learning_questions FOR EACH ROW EXECUTE FUNCTION public.validate_published_source();